import { Check, Copy, Download } from "lucide-react";
import { useEffect, useRef, useState } from "react";

import { useSource } from "./use-source";
import { Button } from "@/components/ui/button";
import { ScrollArea, ScrollBar } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";

/**
 * The file as the edits so far leave it, with the lines they changed marked. What an editor saves is this text: the
 * same file, one value changed where you changed one.
 */
export function Source({
  source,
  name = "video.tsx",
  className,
}: {
  source: string;
  name?: string;
  className?: string;
}) {
  const { text, changed, skipped } = useSource(source);
  const [copied, setCopied] = useState(false);
  const lines = text.split("\n");
  const view = useRef<HTMLPreElement>(null);
  // The first changed line comes into view, so an edit made elsewhere is seen landing in the file.
  const first = Math.min(...changed);
  useEffect(() => {
    if (Number.isFinite(first))
      view.current?.querySelector(`[data-line="${first}"]`)?.scrollIntoView({ block: "center" });
  }, [first]);
  const copy = async () => {
    await navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 1200);
  };
  const download = () => {
    const url = URL.createObjectURL(new Blob([text], { type: "text/plain" }));
    const a = Object.assign(document.createElement("a"), { href: url, download: name });
    a.click();
    URL.revokeObjectURL(url);
  };
  return (
    <div className={cn("flex h-full min-h-0 flex-col", className)} data-editor-source="">
      <div className="flex items-center gap-2 border-b px-3 py-1.5 text-xs text-muted-foreground">
        <span className="font-mono">{name}</span>
        <span>{changed.size === 0 ? "unchanged" : `${changed.size} line${changed.size === 1 ? "" : "s"} changed`}</span>
        {skipped.length > 0 && <span className="text-destructive">{skipped.length} edit(s) not written</span>}
        <div className="ml-auto flex gap-1">
          <Button variant="ghost" size="sm" onClick={copy}>
            {copied ? <Check /> : <Copy />} Copy
          </Button>
          <Button variant="ghost" size="sm" onClick={download}>
            <Download /> Download
          </Button>
        </div>
      </div>
      <ScrollArea className="min-h-0 flex-1">
        <pre ref={view} className="py-2 font-mono text-xs leading-5">
          {lines.map((line, i) => (
            <div
              // biome-ignore lint/suspicious/noArrayIndexKey: a line's place is its identity here.
              key={i}
              data-line={i}
              data-changed={changed.has(i) || undefined}
              className={cn("flex pr-4", changed.has(i) && "bg-primary/10")}
            >
              <span
                className={cn(
                  "w-10 shrink-0 pr-3 text-right text-muted-foreground/60 select-none",
                  changed.has(i) && "border-l-2 border-primary text-primary",
                )}
              >
                {i + 1}
              </span>
              <code className="whitespace-pre">{line || " "}</code>
            </div>
          ))}
        </pre>
        <ScrollBar orientation="horizontal" />
      </ScrollArea>
    </div>
  );
}

import { useMemo } from "react";

import { useEditor } from "@uberscene/editor";
import { foldToSource } from "@uberscene/sdk";

export interface SourceView {
  /** The file with every edit so far written into it. */
  readonly text: string;
  /** The 0-based lines of `text` that differ from the file as it was opened. */
  readonly changed: ReadonlySet<number>;
  /** Edits the fold could not write, with the reason (an element built by code, for one). */
  readonly skipped: readonly { readonly id: string; readonly reason: string }[];
}

/** The file as the edits so far leave it: the executor's log folded into the opened text. */
export function useSource(original: string): SourceView {
  const { state, executor } = useEditor();
  return useMemo(() => {
    if (!executor || executor.log().net.size === 0) return { text: original, changed: new Set<number>(), skipped: [] };
    const folded = foldToSource(original, executor.log(), state);
    return { text: folded.text, changed: changedLines(original, folded.text), skipped: folded.skipped };
  }, [original, executor, state]);
}

/** The lines of `after` that a line diff against `before` does not keep (a longest common subsequence). */
function changedLines(before: string, after: string): Set<number> {
  const a = before.split("\n");
  const b = after.split("\n");
  // The common head and tail are kept as they are; only the middle is diffed.
  let head = 0;
  while (head < a.length && head < b.length && a[head] === b[head]) head++;
  let tail = 0;
  while (tail < a.length - head && tail < b.length - head && a[a.length - 1 - tail] === b[b.length - 1 - tail]) tail++;
  const x = a.slice(head, a.length - tail);
  const y = b.slice(head, b.length - tail);
  const lcs: number[][] = Array.from({ length: x.length + 1 }, () => new Array<number>(y.length + 1).fill(0));
  for (let i = x.length - 1; i >= 0; i--)
    for (let j = y.length - 1; j >= 0; j--)
      lcs[i]![j] = x[i] === y[j] ? lcs[i + 1]![j + 1]! + 1 : Math.max(lcs[i + 1]![j]!, lcs[i]![j + 1]!);
  const changed = new Set<number>();
  let i = 0;
  let j = 0;
  while (j < y.length) {
    if (i < x.length && x[i] === y[j]) {
      i++;
      j++;
    } else if (i < x.length && lcs[i + 1]![j]! >= lcs[i]![j + 1]!) i++;
    else changed.add(head + j++);
  }
  return changed;
}
